// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    // fuzz: actor is any address; the property: only the deployer (owner) can succeed
    function testFuzz_property(address actor) public {
        // keep actor wide but avoid the zero address because prank to address(0) isn't meaningful
        vm.assume(actor != address(0));

        bool ok;
        // try calling sudicideAnyone as the fuzzed actor
        vm.prank(actor);
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: only the deployer (this contract at setUp used msg.sender) is allowed.
        // Since setUp deployed c from this test contract, the owner is address(this).
        // Therefore for ALL actor values, the call by actor must succeed iff actor == address(this).
        // We assert the forward direction as a universal property by checking that if actor != address(this)
        // then the call did NOT succeed. This holds for the reference; the mutant (removing the require)
        // will allow some non-owner actor to succeed, causing this assertion to fail for those inputs.
        if (actor != address(this)) {
            assertTrue(!ok);
        } else {
            // when actor == address(this), the call should succeed
            assertTrue(ok);
        }
    }
}
